/* One scripted step: characters to type, text that must (and must not)
 * appear in the console output, and the mode afterwards. */
typedef struct {
    const char *input;
    const char *expect[4];
    const char *reject;
    MenuMode    mode_after;
} demo_step_t;

static int         g_checks;
static int         g_fails;
static char        g_first_fail[256];

/**
 * @brief Count one check; report and remember a failure.
 * @param ok  Check result.
 * @param msg Description of what was checked.
 * @return None.
 */
static void demo_check(int ok, const char *msg)
{
    g_checks++;
    if (!ok) {
        g_fails++;
        if (g_first_fail[0] == '\0') {
            (void)snprintf(g_first_fail, sizeof(g_first_fail), "%s", msg);
        }
        printf("\nCHECK FAILED: %s\n", msg);
    }
}

/**
 * @brief Type a string into the line editor, one character at a time.
 * @param s Characters (may contain CR, ESC sequences and control codes).
 * @return None.
 */
static void demo_type(const char *s)
{
    for (; *s != '\0'; s++) {
        Menu_InputChar((unsigned char)*s);
    }
}

/**
 * @brief Check that every " - " separator of the listing lines (lines that
 *        start with two spaces) in a text block sits in one column.
 * @param text Console output of one help listing.
 * @return 1 when aligned and at least two lines were found, else 0.
 */
static int demo_aligned(const char *text)
{
    int col = -1;
    int lines = 0;
    const char *p = text;
    while (*p != '\0') {
        const char *eol = strchr(p, '\n');
        size_t len = (eol != NULL) ? (size_t)(eol - p) : strlen(p);
        if (len > 2u && p[0] == ' ' && p[1] == ' ') {
            const char *sep = strstr(p, " - ");
            if (sep != NULL && (eol == NULL || sep < eol)) {
                int c = (int)(sep - p);
                if (col < 0) {
                    col = c;
                } else if (c != col) {
                    return 0;
                }
                lines++;
            }
        }
        if (eol == NULL) {
            break;
        }
        p = eol + 1;
    }
    return (lines >= 2) ? 1 : 0;
}

/**
 * @brief Check one word of the classifier register model.
 * @param off  Offset in the classifier window.
 * @param want Expected value.
 * @param msg  Description.
 * @return None.
 */
static void demo_cls(uint32_t off, uint32_t want, const char *msg)
{
    char buf[160];
    uint32_t got = host_model_cls_peek(off);
    (void)snprintf(buf, sizeof(buf), "classifier register 0x%03X (%s): 0x%08X, expected 0x%08X", (unsigned)off, msg,
                   (unsigned)got, (unsigned)want);
    demo_check(got == want, buf);
}

/**
 * @brief Run the CLI against the classifier register model: boot
 *        configuration, every classifier command written through the driver,
 *        counters read back.
 * @return None.
 */
static void demo_classifier(void)
{
    uint32_t mem_boot[RTLNET_CLS_WINDOW_BYTES / 4u];
    host_model_set_core(RTLNET_PLAT_PROT_BASE, RTLNET_ID_PROT);
    host_model_set_wrapper(1, 0x00010810u);            /* CPU path with the classifier */
    host_model_set_core(RTLNET_PLAT_CLS_BASE, RTLNET_ID_CLS);
    rtlnet_features_rediscover();
    host_capture_clear();
    demo_type("enable\r");
    demo_type("configure terminal\r");

    /* The running configuration of the scripted session (storm 20/200 disabled, pass-on-match, MAC 3, EtherType
     * pair 4, ACL 1, policer 1) is written by the boot call when it differs from the default. */
    demo_check(cpupath_init() == CPUPATH_OK, "cpupath_init with the classifier present");
    demo_check(cpupath_cls_present() == 1, "classifier reported present");
    demo_cls(RTLNET_CLS_REG_CTRL, RTLNET_CLS_MODE_PASS_ON_MATCH, "MODE pass-on-match");
    demo_cls(RTLNET_CLS_REG_POLICER(0) + RTLNET_CLS_POL_LIMIT, 20u, "policer 0 limit");
    demo_cls(RTLNET_CLS_REG_POLICER(0) + RTLNET_CLS_POL_WINDOW, 200u, "policer 0 window");
    demo_cls(RTLNET_CLS_REG_POLICER(0) + RTLNET_CLS_POL_CTRL, 0u, "policer 0 disabled by no storm-control");
    demo_cls(RTLNET_CLS_REG_POLICER(1) + RTLNET_CLS_POL_LIMIT, 5u, "policer 1 limit");
    demo_cls(RTLNET_CLS_REG_POLICER(1) + RTLNET_CLS_POL_WINDOW, 50u, "policer 1 window");
    demo_cls(RTLNET_CLS_REG_POLICER(1) + RTLNET_CLS_POL_CTRL, RTLNET_CLS_POL_CTRL_ENABLE, "policer 1 enabled");
    /* MAC 3: src 02:00:00:00:00:01, gate -> the MAC table gates (CLASSIFY clear). */
    demo_cls(RTLNET_CLS_REG_ENTRY(RTLNET_CLS_TABLE_MAC, 3u) + RTLNET_CLS_ENT_SRC_LO, 0x00000001u, "MAC 3 value low");
    demo_cls(RTLNET_CLS_REG_ENTRY(RTLNET_CLS_TABLE_MAC, 3u) + RTLNET_CLS_ENT_CTRL,
             RTLNET_CLS_ENT_VALID | RTLNET_CLS_ENT_SRC_EN | 0x0200u, "MAC 3 control word");
    demo_cls(RTLNET_CLS_REG_ENTRY(RTLNET_CLS_TABLE_MAC, 0u) + RTLNET_CLS_ENT_CTRL,
             RTLNET_CLS_ENT_VALID | RTLNET_CLS_ENT_DST_EN | RTLNET_CLS_ENT_POLICE_EN | 0xFFFFu, "MAC 0 control word");
    demo_cls(RTLNET_CLS_REG_TABLE_MODE(RTLNET_CLS_TABLE_MAC), RTLNET_CLS_TM_ENABLE, "MAC table enabled, gating");
    /* EtherType pair 4 = entries 8 and 9: 0x88B5..0x88B6 policed by policer 2, classify-only range table. */
    demo_cls(RTLNET_CLS_REG_ENTRY(RTLNET_CLS_TABLE_ETHERTYPE, 8u) + RTLNET_CLS_ENT_SRC_LO, 0x88B5u, "EtherType low");
    demo_cls(RTLNET_CLS_REG_ENTRY(RTLNET_CLS_TABLE_ETHERTYPE, 9u) + RTLNET_CLS_ENT_SRC_LO, 0x88B6u, "EtherType high");
    demo_cls(RTLNET_CLS_REG_ENTRY(RTLNET_CLS_TABLE_ETHERTYPE, 8u) + RTLNET_CLS_ENT_CTRL,
             RTLNET_CLS_ENT_VALID | RTLNET_CLS_ENT_SRC_EN | RTLNET_CLS_ENT_POLICE_EN | (2u << RTLNET_CLS_ENT_POLICER_SHIFT),
             "EtherType control word");
    demo_cls(RTLNET_CLS_REG_TABLE_MODE(RTLNET_CLS_TABLE_ETHERTYPE),
             RTLNET_CLS_TM_ENABLE | ((uint32_t)RTLNET_CLS_CMP_RANGE << RTLNET_CLS_TM_COMPARE_SHIFT) | RTLNET_CLS_TM_CLASSIFY,
             "EtherType table range, classify-only");
    /* ACL 1: tcp src 192.169.1.0/24 dst any dport 22, police 1 -> tuple table classify-only. */
    demo_cls(RTLNET_CLS_REG_TUPLE(1u) + RTLNET_CLS_TUP_CTRL,
             RTLNET_CLS_TUP_VALID | RTLNET_CLS_TUP_PROTO_EN | RTLNET_CLS_TUP_POLICE_EN | (1u << RTLNET_CLS_TUP_POLICER_SHIFT) | 6u,
             "ACL 1 control word");
    demo_cls(RTLNET_CLS_REG_TUPLE(1u) + RTLNET_CLS_TUP_SRC_IP, 0xC0A90100u, "ACL 1 source");
    demo_cls(RTLNET_CLS_REG_TUPLE(1u) + RTLNET_CLS_TUP_SRC_MASK, 0xFFFFFF00u, "ACL 1 source mask");
    demo_cls(RTLNET_CLS_REG_TUPLE(1u) + RTLNET_CLS_TUP_DST_MASK, 0u, "ACL 1 destination mask (any)");
    demo_cls(RTLNET_CLS_REG_TUPLE(1u) + RTLNET_CLS_TUP_DPORT, (22u << 16) | 22u, "ACL 1 destination port 22");
    demo_cls(RTLNET_CLS_REG_TUPLE(1u) + RTLNET_CLS_TUP_SPORT, 0xFFFF0000u, "ACL 1 source port any");
    demo_cls(RTLNET_CLS_REG_TABLE_MODE(RTLNET_CLS_TABLE_TUPLE), RTLNET_CLS_TM_ENABLE | RTLNET_CLS_TM_CLASSIFY,
             "tuple table enabled, classify-only");

    /* classifier defaults: the broadcast storm configuration through the CLI (whole configuration rewritten). */
    demo_type("classifier defaults\r");
    demo_cls(RTLNET_CLS_REG_CTRL, RTLNET_CLS_MODE_PASS_ALL, "MODE pass-all after defaults");
    demo_cls(RTLNET_CLS_REG_POLICER(0) + RTLNET_CLS_POL_LIMIT, 10u, "storm limit 10");
    demo_cls(RTLNET_CLS_REG_POLICER(0) + RTLNET_CLS_POL_WINDOW, 100u, "storm window 100");
    demo_cls(RTLNET_CLS_REG_POLICER(0) + RTLNET_CLS_POL_CTRL, RTLNET_CLS_POL_CTRL_ENABLE, "storm policer enabled");
    demo_cls(RTLNET_CLS_REG_TABLE_MODE(RTLNET_CLS_TABLE_MAC), RTLNET_CLS_TM_ENABLE | RTLNET_CLS_TM_CLASSIFY,
             "MAC table classify-only");
    demo_cls(RTLNET_CLS_REG_TABLE_MODE(RTLNET_CLS_TABLE_ETHERTYPE), 0u, "EtherType table cleared");
    demo_cls(RTLNET_CLS_REG_TABLE_MODE(RTLNET_CLS_TABLE_TUPLE), 0u, "tuple table cleared");
    demo_cls(RTLNET_CLS_REG_POLICER(1) + RTLNET_CLS_POL_CTRL, 0u, "policer 1 cleared");
    for (uint32_t i = 0; i < RTLNET_CLS_WINDOW_BYTES / 4u; i++) {
        mem_boot[i] = host_model_cls_peek(4u * i);
    }

    /* The boot call on the default configuration (rtlnet_classifier_config_bcast_storm) leaves the same
     * register state as the generic whole-configuration write above. */
    host_model_set_core(RTLNET_PLAT_CLS_BASE, RTLNET_ID_CLS);
    demo_check(cpupath_init() == CPUPATH_OK, "cpupath_init on the default configuration");
    {
        int same = 1;
        for (uint32_t i = 0; i < RTLNET_CLS_WINDOW_BYTES / 4u; i++) {
            if (host_model_cls_peek(4u * i) != mem_boot[i]) {
                same = 0;
            }
        }
        demo_check(same, "config_bcast_storm and the generic configuration write leave identical registers");
    }

    /* Storm-control commands in the interface context. */
    demo_type("interface eth0\r");
    demo_type("storm-control broadcast 7 30\r");
    demo_cls(RTLNET_CLS_REG_POLICER(0) + RTLNET_CLS_POL_LIMIT, 7u, "storm-control limit");
    demo_cls(RTLNET_CLS_REG_POLICER(0) + RTLNET_CLS_POL_WINDOW, 30u, "storm-control window");
    demo_type("storm-control broadcast disable\r");
    demo_cls(RTLNET_CLS_REG_POLICER(0) + RTLNET_CLS_POL_CTRL, 0u, "storm-control disable");
    demo_cls(RTLNET_CLS_REG_POLICER(0) + RTLNET_CLS_POL_LIMIT, 7u, "limit kept by disable");
    demo_type("storm-control broadcast enable\r");
    demo_cls(RTLNET_CLS_REG_POLICER(0) + RTLNET_CLS_POL_CTRL, RTLNET_CLS_POL_CTRL_ENABLE, "storm-control enable");
    demo_type("end\r");

    /* Counters read back through the driver. */
    host_model_cls_poke(RTLNET_CLS_REG_COUNTER(RTLNET_CLS_CNT_FRAMES), 100u);
    host_model_cls_poke(RTLNET_CLS_REG_COUNTER(RTLNET_CLS_CNT_PASSED), 62u);
    host_model_cls_poke(RTLNET_CLS_REG_COUNTER(RTLNET_CLS_CNT_DROPPED), 38u);
    host_model_cls_poke(RTLNET_CLS_REG_COUNTER(RTLNET_CLS_CNT_POLICE_DROPPED), 38u);
    host_model_cls_poke(RTLNET_CLS_REG_POLICER(0) + RTLNET_CLS_POL_SEEN, 50u);
    host_model_cls_poke(RTLNET_CLS_REG_POLICER(0) + RTLNET_CLS_POL_PASSED, 12u);
    host_model_cls_poke(RTLNET_CLS_REG_POLICER(0) + RTLNET_CLS_POL_DROPPED, 38u);
    host_capture_clear();
    demo_type("show storm-control\r");
    demo_check(strstr(host_capture_text(), "enabled, 7 frames per 30 ms") != NULL &&
               strstr(host_capture_text(), "seen 50, passed 12, dropped 38") != NULL,
               "show storm-control reads the policer through the driver");
    host_capture_clear();
    demo_type("show classifier\r");
    demo_check(strstr(host_capture_text(), "Hardware        : mode pass-all") != NULL &&
               strstr(host_capture_text(), "delay line 31 beats, verdict latency 23 clocks") != NULL &&
               strstr(host_capture_text(), "frames 100, passed 62, dropped 38 (mode 0, policers 38") != NULL,
               "show classifier reads state and counters through the driver");
    host_capture_clear();
    demo_type("show cpu-path\r");
    demo_check(strstr(host_capture_text(), "Classifier      : present, mode pass-all") != NULL, "show cpu-path: classifier present");
    demo_type("clear counters\r");

    /* Out of range indices stay errors with the classifier present. */
    host_capture_clear();
    demo_type("configure terminal\r");
    demo_type("classifier ethertype 8 0x88b5 gate\r");
    demo_check(strstr(host_capture_text(), "% Invalid entry (0..7)") != NULL ||
               strstr(host_capture_text(), "entry (0..7)") != NULL, "EtherType entry 8 rejected (pairs 0..7)");
    host_capture_clear();
    demo_type("classifier mac 3 src 02:00:00:00:00:01 mask ff:ff:ff:00:00:00 gate\r");
    demo_check(strstr(host_capture_text(), "% ") != NULL, "MAC mask is not accepted");
    demo_type("end\r");
    demo_type("disable\r");
    host_model_set_core(RTLNET_PLAT_CLS_BASE, 0u);
}


/* ---------------------------------------------------------------------------
 * Checksum offload: discovery of every build combination, the order of the
 * register and lwIP-flag changes, the receive trailer policy and the CLI.
 * ------------------------------------------------------------------------- */
#define DEMO_CAPS_BOTH   (RTLNET_TXO_CAPS_TX_PRESENT | RTLNET_TXO_CAPS_RX_PRESENT | RTLNET_TXO_CAPS_INS_IP | \
                          RTLNET_TXO_CAPS_INS_TCP | RTLNET_TXO_CAPS_INS_UDP | RTLNET_TXO_CAPS_VLAN | (8u << 8) | (1518u << 16))
#define DEMO_CAPS_TX     (DEMO_CAPS_BOTH & ~RTLNET_TXO_CAPS_RX_PRESENT)
#define DEMO_CAPS_RX     (DEMO_CAPS_BOTH & ~RTLNET_TXO_CAPS_TX_PRESENT)
#define DEMO_CPU_QUEUES  0x0810u
#define DEMO_FLAGS_ALL   0xFFFFu
#define DEMO_CHECK_BITS  (RTLNET_CS_CHECK_IP | RTLNET_CS_CHECK_TCP | RTLNET_CS_CHECK_UDP)
#define DEMO_GEN_BITS    (RTLNET_CS_GEN_IP | RTLNET_CS_GEN_TCP | RTLNET_CS_GEN_UDP)

/**
 * @brief Build a DMA buffer holding a frame of len bytes, its padding and a receive trailer.
 * @param buf   Buffer of at least 2048 bytes.
 * @param len   Frame length.
 * @param flags Trailer flags.
 * @param sum   Trailer folded sum.
 * @return Transfer length (roundup8(len) + 8).
 */
static uint32_t demo_trailer_buf(uint8_t *buf, uint32_t len, uint16_t flags, uint16_t sum)
{
    uint32_t n = (len + 7u) & ~7u;
    memset(buf, 0, 2048u);
    for (uint32_t i = 0; i < len; i++) {
        buf[i] = (uint8_t)(i * 5u + 1u);
    }
    buf[n + 0u] = (uint8_t)len;
    buf[n + 1u] = (uint8_t)(len >> 8);
    buf[n + 2u] = (uint8_t)sum;
    buf[n + 3u] = (uint8_t)(sum >> 8);
    buf[n + 4u] = (uint8_t)flags;
    buf[n + 5u] = (uint8_t)(flags >> 8);
    buf[n + 6u] = 34u;
    buf[n + 7u] = 0xA5u;
    return n + 8u;
}

/**
 * @brief Index of the first logged event of a kind at or after a position.
 * @param kind HOST_EV_*.
 * @param from First index to look at.
 * @return Index, or -1 when none.
 */
static int demo_find_event(int kind, unsigned from)
{
    for (unsigned i = from; i < host_events_count(); i++) {
        if (host_event(i)->kind == kind) {
            return (int)i;
        }
    }
    return -1;
}

/**
 * @brief Set up one build combination and run the discovery again.
 * @param prot     1 when the wrapper answers.
 * @param cpu_path 1 when it has the CPU path.
 * @param cpu_caps CPU_CAPS value.
 * @param txo_present 1 when the offload window answers.
 * @param txo_caps Offload CAPS.
 * @return None.
 */
static void demo_build(int prot, int cpu_path, uint32_t cpu_caps, int txo_present, uint32_t txo_caps)
{
    host_model_set_core(RTLNET_PLAT_PROT_BASE, prot ? RTLNET_ID_PROT : 0u);
    host_model_set_wrapper(cpu_path, cpu_caps);
    host_model_set_core(RTLNET_PLAT_CLS_BASE, (cpu_caps & RTLNET_PROTO_CPU_CAPS_CLASSIFIER) ? RTLNET_ID_CLS : 0u);
    host_model_txo_set(txo_present, txo_caps);
    host_capture_clear();
    rtlnet_features_rediscover();
}

/**
 * @brief The offload scenarios.
 * @return None.
 */
static void demo_offload(void)
{
    uint8_t buf[2048];
    uint32_t len;
    uint32_t xfer;
    const rtlnet_features_t *f;
    const rtlnet_offload_state_t *st;
    int e_ctrl;
    int e_flags;
    int e_status;
    unsigned n0;

    /* ---- Discovery of every combination. */
    demo_build(0, 0, 0u, 0, 0u);
    f = rtlnet_features();
    demo_check(f->discovered && !f->wrapper_ok && !f->tx_present && !f->rx_present && f->errors == 0u, "discovery: no wrapper");
    demo_check(rtlnet_offload_supported() == 0u, "discovery: nothing to offload without the wrapper");
    demo_build(1, 0, 0u, 0, 0u);
    f = rtlnet_features();
    demo_check(f->wrapper_ok && !f->cpu_path && !f->tx_present && !f->cls_present && f->errors == 0u, "discovery: no CPU path");
    demo_build(1, 1, DEMO_CPU_QUEUES, 0, 0u);
    f = rtlnet_features();
    demo_check(f->cpu_path && !f->cls_present && !f->tx_present && !f->rx_present && f->errors == 0u,
               "discovery: CPU path with no optional block");
    demo_build(1, 1, 0x00070000u | DEMO_CPU_QUEUES, 1, DEMO_CAPS_BOTH);
    f = rtlnet_features();
    demo_check(f->cls_present && f->tx_present && f->rx_present && f->errors == 0u && f->block_caps == DEMO_CAPS_BOTH,
               "discovery: classifier and both offload paths");
    demo_check(rtlnet_offload_supported() == RTLNET_OFFLOAD_ALL, "supported: tx-ip, tx-l4 and rx");
    demo_build(1, 1, 0x00020000u | DEMO_CPU_QUEUES, 1, DEMO_CAPS_TX);
    f = rtlnet_features();
    demo_check(!f->cls_present && f->tx_present && !f->rx_present && f->errors == 0u, "discovery: offload TX only");
    demo_check(rtlnet_offload_supported() == (RTLNET_OFFLOAD_TX_IP | RTLNET_OFFLOAD_TX_L4), "supported: TX bits only");
    demo_build(1, 1, 0x00040000u | DEMO_CPU_QUEUES, 1, DEMO_CAPS_RX);
    f = rtlnet_features();
    demo_check(!f->tx_present && f->rx_present && f->errors == 0u, "discovery: offload RX only");
    demo_check(rtlnet_offload_supported() == RTLNET_OFFLOAD_RX, "supported: RX bit only");
    demo_build(1, 1, 0x00060000u | DEMO_CPU_QUEUES, 1, DEMO_CAPS_RX);
    f = rtlnet_features();
    demo_check(f->errors == 1u && !f->tx_present && !f->rx_present, "discovery: CPU_CAPS and core CAPS disagree: absent");
    demo_check(strstr(host_capture_text(), "mismatch") != NULL, "discovery: the mismatch is logged");
    demo_build(1, 1, 0x00060000u | DEMO_CPU_QUEUES, 0, 0u);
    f = rtlnet_features();
    demo_check(f->errors == 1u && !f->tx_present && !f->rx_present, "discovery: advertised but the window is empty: absent");
    demo_build(1, 1, 0x00010000u | DEMO_CPU_QUEUES, 0, 0u);
    host_model_set_core(RTLNET_PLAT_CLS_BASE, 0u);
    host_capture_clear();
    rtlnet_features_rediscover();
    f = rtlnet_features();
    demo_check(f->errors == 1u && !f->cls_present, "discovery: classifier advertised but absent: error, absent");
    demo_build(1, 1, DEMO_CPU_QUEUES, 1, DEMO_CAPS_BOTH);
    f = rtlnet_features();
    demo_check(!f->tx_present && !f->rx_present && rtlnet_offload_supported() == 0u,
               "discovery: a window that answers but is not advertised is not used");

    /* ---- apply(): absent core, nothing to change, flags all software. */
    host_events_clear();
    demo_check(rtlnet_offload_apply(RTLNET_OFFLOAD_ALL) == RTLNET_OFFLOAD_OK, "apply without a core is a no-op");
    demo_check(demo_find_event(HOST_EV_CTRL_WRITE, 0u) < 0, "apply without a core writes no CTRL");
    demo_check(rtlnet_lwip_get_checksum_ctrl() == DEMO_FLAGS_ALL, "no core: every lwIP checksum in software");

    /* ---- apply(): both paths on from CTRL 0. */
    demo_build(1, 1, 0x00070000u | DEMO_CPU_QUEUES, 1, DEMO_CAPS_BOTH);
    host_events_clear();
    demo_check(rtlnet_offload_apply(RTLNET_OFFLOAD_ALL) == RTLNET_OFFLOAD_OK, "apply(all) from CTRL 0");
    st = rtlnet_offload_state();
    e_ctrl = demo_find_event(HOST_EV_CTRL_WRITE, 0u);
    e_flags = demo_find_event(HOST_EV_FLAGS, 0u);
    demo_check(e_ctrl >= 0 && e_flags > e_ctrl, "turning on: CTRL written before the lwIP GEN flags change");
    demo_check(host_model_txo_ctrl() == RTLNET_OFFLOAD_ALL && st->ctrl == RTLNET_OFFLOAD_ALL, "CTRL reads back 7");
    demo_check(rtlnet_lwip_get_checksum_ctrl() == (DEMO_FLAGS_ALL & ~DEMO_GEN_BITS),
               "GEN flags cleared (from the read-back), CHECK flags still on while the receive trailers are unproven");
    demo_check(st->rx_state == RTLNET_RX_TRAILER_ARMING, "receive trailers: arming");

    /* Frames queued before the change carry no trailer and are checked in software. */
    memset(buf, 0x11, sizeof(buf));
    buf[63] = 0x22u;
    demo_check(rtlnet_offload_rx_frame(buf, 64u, &len) == RTLNET_RXA_DELIVER_RAW && len == 64u,
               "arming: a frame without trailer is delivered whole");
    demo_check((rtlnet_lwip_get_checksum_ctrl() & DEMO_CHECK_BITS) == DEMO_CHECK_BITS, "arming: CHECK flags stay on");
    n0 = host_events_count();
    xfer = demo_trailer_buf(buf, 60u, 0x00E3u, 0xFFFFu);
    demo_check(rtlnet_offload_rx_frame(buf, xfer, &len) == RTLNET_RXA_DELIVER_VERIFIED && len == 60u,
               "first trailer: verified and good, frame length from the trailer");
    demo_check(rtlnet_offload_state()->rx_state == RTLNET_RX_TRAILER_ON, "receive trailers: on");
    demo_check(host_events_count() == n0 + 1u && host_event(n0)->kind == HOST_EV_FLAGS &&
               host_event(n0)->value == (DEMO_FLAGS_ALL & ~DEMO_GEN_BITS & ~DEMO_CHECK_BITS),
               "first trailer clears the CHECK flags");

    /* Policy on trailers. */
    xfer = demo_trailer_buf(buf, 1514u, 0x00A3u, 0x1234u);
    demo_check(rtlnet_offload_rx_frame(buf, xfer, &len) == RTLNET_RXA_DROP_BAD_L4, "verified, bad L4 checksum: drop");
    xfer = demo_trailer_buf(buf, 100u, 0x0001u, 0x0000u);
    demo_check(rtlnet_offload_rx_frame(buf, xfer, &len) == RTLNET_RXA_DROP_BAD_IP, "IPv4 with a bad header: drop");
    xfer = demo_trailer_buf(buf, 61u, 0x0000u, 0x0000u);
    demo_check(rtlnet_offload_rx_frame(buf, xfer, &len) == RTLNET_RXA_DELIVER_UNVERIFIED && len == 61u, "unverified: pass");
    xfer = demo_trailer_buf(buf, 42u, 0x0025u, 0x0000u);
    demo_check(rtlnet_offload_rx_frame(buf, xfer, &len) == RTLNET_RXA_DELIVER_UNVERIFIED, "IPv4 good, UDP checksum 0: pass");
    memset(buf, 0x33, sizeof(buf));
    demo_check(rtlnet_offload_rx_frame(buf, 64u, &len) == RTLNET_RXA_DROP_NO_TRAILER, "rx on: a frame without trailer is dropped");
    st = rtlnet_offload_state();
    demo_check(st->rx_drop_l4 == 1u && st->rx_drop_ip == 1u && st->rx_no_trailer == 1u && st->rx_verified == 1u &&
               st->rx_unverified == 2u && st->rx_trailer_frames == 5u, "receive policy counters");

    /* ---- apply(): turn the transmit L4 offload off, keep tx-ip: GEN flags first, wait for idle, then CTRL. */
    host_model_txo_idle_after(2u);
    host_events_clear();
    demo_check(rtlnet_offload_apply(RTLNET_OFFLOAD_TX_IP | RTLNET_OFFLOAD_RX) == RTLNET_OFFLOAD_OK, "apply(tx-ip + rx)");
    e_flags = demo_find_event(HOST_EV_FLAGS, 0u);
    e_status = demo_find_event(HOST_EV_STATUS_READ, 0u);
    e_ctrl = demo_find_event(HOST_EV_CTRL_WRITE, 0u);
    demo_check(e_flags == 0 && host_event(0)->value == (DEMO_FLAGS_ALL & ~RTLNET_CS_GEN_IP & ~DEMO_CHECK_BITS),
               "turning tx-l4 off: the GEN_TCP / GEN_UDP flags are set before anything else");
    demo_check(e_status > e_flags && e_ctrl > e_status, "turning tx-l4 off: STATUS.TX_IDLE polled before CTRL is written");
    demo_check(host_event((unsigned)e_ctrl - 1u)->kind == HOST_EV_STATUS_READ && host_event((unsigned)e_ctrl - 1u)->value == 1u,
               "CTRL written after TX_IDLE read 1");
    demo_check(host_model_txo_ctrl() == (RTLNET_OFFLOAD_TX_IP | RTLNET_OFFLOAD_RX), "CTRL = tx-ip + rx");

    /* ---- Receive off: CHECK flags first, CTRL second, trailers parsed until the first raw frame. */
    host_events_clear();
    demo_check(rtlnet_offload_apply(RTLNET_OFFLOAD_TX_IP) == RTLNET_OFFLOAD_OK, "apply(tx-ip): receive off");
    e_flags = demo_find_event(HOST_EV_FLAGS, 0u);
    e_ctrl = demo_find_event(HOST_EV_CTRL_WRITE, 0u);
    demo_check(e_flags == 0 && host_event(0)->value == (DEMO_FLAGS_ALL & ~RTLNET_CS_GEN_IP) && e_ctrl > e_flags,
               "turning rx off: CHECK flags set before CTRL is cleared");
    demo_check(demo_find_event(HOST_EV_STATUS_READ, 0u) < 0, "turning rx off needs no TX idle wait");
    demo_check(rtlnet_offload_state()->rx_state == RTLNET_RX_TRAILER_DRAINING, "receive trailers: draining");
    xfer = demo_trailer_buf(buf, 70u, 0x0000u, 0u);
    demo_check(rtlnet_offload_rx_frame(buf, xfer, &len) == RTLNET_RXA_DELIVER_UNVERIFIED && len == 70u,
               "draining: a frame past the offload still carries its trailer");
    memset(buf, 0x44, sizeof(buf));
    demo_check(rtlnet_offload_rx_frame(buf, 128u, &len) == RTLNET_RXA_DELIVER_RAW && len == 128u,
               "draining: the first raw frame is delivered whole");
    demo_check(rtlnet_offload_state()->rx_state == RTLNET_RX_TRAILER_OFF, "receive trailers: off after the first raw frame");
    demo_check(rtlnet_offload_rx_frame(buf, 1000u, &len) == RTLNET_RXA_DELIVER_RAW && len == 1000u, "off: frames are raw");

    /* ---- Timeout: TX never goes idle; CTRL stays, software checksums come back. */
    host_model_txo_idle_after(0xFFFFFFFFu);
    host_events_clear();
    demo_check(rtlnet_offload_apply(0u) == RTLNET_OFFLOAD_ERR_TIMEOUT, "apply(0) with TX never idle times out");
    demo_check(demo_find_event(HOST_EV_CTRL_WRITE, 0u) < 0 && host_model_txo_ctrl() == RTLNET_OFFLOAD_TX_IP,
               "timeout: CTRL left on");
    demo_check(rtlnet_lwip_get_checksum_ctrl() == (DEMO_FLAGS_ALL & ~RTLNET_CS_GEN_IP), "timeout: flags follow the CTRL read-back");
    demo_check(rtlnet_offload_state()->idle_timeouts == 1u, "timeout counted");
    host_model_txo_idle_after(2u);
    demo_check(rtlnet_offload_apply(0u) == RTLNET_OFFLOAD_OK && host_model_txo_ctrl() == 0u &&
               rtlnet_lwip_get_checksum_ctrl() == DEMO_FLAGS_ALL, "everything off: CTRL 0, every checksum in software");

    /* ---- Read-back mismatch: the flags follow the hardware, not the request. */
    host_model_txo_stuck(RTLNET_OFFLOAD_TX_L4);
    demo_check(rtlnet_offload_apply(RTLNET_OFFLOAD_TX_L4) == RTLNET_OFFLOAD_ERR_IO, "stuck CTRL bit: read-back mismatch reported");
    demo_check(rtlnet_lwip_get_checksum_ctrl() == DEMO_FLAGS_ALL, "stuck CTRL bit: lwIP keeps its checksums");
    host_model_txo_stuck(0u);
    demo_check(rtlnet_offload_apply(RTLNET_OFFLOAD_TX_L4) == RTLNET_OFFLOAD_OK &&
               rtlnet_lwip_get_checksum_ctrl() == (DEMO_FLAGS_ALL & ~(RTLNET_CS_GEN_TCP | RTLNET_CS_GEN_UDP)),
               "tx-l4 on clears GEN_TCP and GEN_UDP only");

    /* ---- A restart finds CTRL as the previous run left it. */
    host_model_txo_set_ctrl(RTLNET_OFFLOAD_ALL);
    rtlnet_features_rediscover();
    host_events_clear();
    demo_check(rtlnet_offload_apply(RTLNET_OFFLOAD_TX_IP) == RTLNET_OFFLOAD_OK && host_model_txo_ctrl() == RTLNET_OFFLOAD_TX_IP,
               "restart with CTRL 7: reconciled to the request");
    demo_check(host_event(0)->kind == HOST_EV_FLAGS, "restart: flags first when bits go off");

    /* ---- Single-path builds. */
    demo_build(1, 1, 0x00020000u | DEMO_CPU_QUEUES, 1, DEMO_CAPS_TX);
    demo_check(rtlnet_offload_apply(RTLNET_OFFLOAD_ALL) == RTLNET_OFFLOAD_OK &&
               host_model_txo_ctrl() == (RTLNET_OFFLOAD_TX_IP | RTLNET_OFFLOAD_TX_L4) &&
               rtlnet_offload_state()->rx_state == RTLNET_RX_TRAILER_OFF &&
               (rtlnet_lwip_get_checksum_ctrl() & DEMO_CHECK_BITS) == DEMO_CHECK_BITS,
               "TX-only build: the request is masked, receive checks stay in software");
    demo_build(1, 1, 0x00040000u | DEMO_CPU_QUEUES, 1, DEMO_CAPS_RX);
    demo_check(rtlnet_offload_apply(RTLNET_OFFLOAD_ALL) == RTLNET_OFFLOAD_OK && host_model_txo_ctrl() == RTLNET_OFFLOAD_RX &&
               (rtlnet_lwip_get_checksum_ctrl() & DEMO_GEN_BITS) == DEMO_GEN_BITS &&
               rtlnet_offload_state()->rx_state == RTLNET_RX_TRAILER_ARMING,
               "RX-only build: transmit checksums stay in software");

    /* ---- The CLI. */
    demo_build(1, 1, 0x00070000u | DEMO_CPU_QUEUES, 1, DEMO_CAPS_BOTH);
    host_model_set_core(RTLNET_PLAT_CLS_BASE, RTLNET_ID_CLS);
    host_capture_clear();
    demo_type("enable\r");
    demo_type("show offload\r");
    demo_check(strstr(host_capture_text(), "Confirmed       : classifier yes, offload TX yes, offload RX yes") != NULL,
               "show offload: discovery");
    demo_check(strstr(host_capture_text(), "zero-copy RX") != NULL && strstr(host_capture_text(), "lwIP flags") != NULL,
               "show offload: lwIP flags and build options");
    demo_check(strstr(host_capture_text(), "MISMATCH:") == NULL, "show offload: flags agree with CTRL");
    demo_check(rtlnet_offload_apply(RTLNET_OFFLOAD_ALL) == RTLNET_OFFLOAD_OK, "apply(all) for the CLI");
    rtlnet_lwip_set_checksum_ctrl(DEMO_FLAGS_ALL);
    host_capture_clear();
    demo_type("show offload\r");
    demo_check(strstr(host_capture_text(), "% MISMATCH: lwIP flags 0xFFFF") != NULL, "show offload: MISMATCH line when lwIP disagrees");
    demo_type("configure terminal\r");
    host_capture_clear();
    demo_type("offload tx-l4 off\r");
    demo_check(host_model_txo_ctrl() == (RTLNET_OFFLOAD_TX_IP | RTLNET_OFFLOAD_RX), "offload tx-l4 off: CTRL");
    demo_type("offload rx off\r");
    demo_check(host_model_txo_ctrl() == RTLNET_OFFLOAD_TX_IP, "offload rx off: CTRL");
    demo_type("offload bogus on\r");
    demo_check(strstr(host_capture_text(), "% Invalid offload") != NULL, "offload: bad word");
    demo_type("offload rx maybe\r");
    demo_check(strstr(host_capture_text(), "% Invalid state") != NULL, "offload: bad state");
    host_capture_clear();
    demo_type("end\r");
    demo_type("show running-config\r");
    demo_check(strstr(host_capture_text(), "offload tx-l4 off") != NULL && strstr(host_capture_text(), "offload rx off") != NULL &&
               strstr(host_capture_text(), "offload tx-ip off") == NULL, "running-config lists the offloads that are off");
    host_capture_clear();
    demo_type("show version\r");
    demo_check(strstr(host_capture_text(), "classifier yes, checksum offload TX yes, RX yes") != NULL, "show version: CPU path blocks");
    demo_type("configure terminal\r");
    demo_type("offload all on\r");
    demo_type("end\r");
    demo_check(host_model_txo_ctrl() == RTLNET_OFFLOAD_ALL, "offload all on: CTRL 7");
    host_model_txo_set(0, 0u);
    host_model_set_wrapper(0, 0u);
    host_model_set_core(RTLNET_PLAT_PROT_BASE, 0u);
    host_model_set_core(RTLNET_PLAT_CLS_BASE, 0u);
    rtlnet_features_rediscover();
    host_capture_clear();
    demo_type("show offload\r");
    demo_check(strstr(host_capture_text(), "not present in this build") != NULL, "show offload without the core");
    demo_type("disable\r");
}

/**
 * @brief DDR3 path: show ddr without and with the arbiter, ddr test (default size, a given size, bad
 *        arguments), calibration refused, the memory test catching a stuck address line and a stuck
 *        data bit, and the arbiter counters clearing.
 * @return None.
 */
static void demo_ddr(void)
{
    demo_type("enable\r");

    /* Without the arbiter window and without calibration. */
    host_model_ddr_set(0, 0);
    host_model_ddr_clear();
    host_capture_clear();
    demo_type("show ddr\r");
    demo_check(strstr(host_capture_text(), "Calibration     : NOT done") != NULL &&
               strstr(host_capture_text(), "DDR3 arbiter not present in this build") != NULL, "show ddr: no arbiter, not calibrated");
    host_capture_clear();
    demo_type("ddr test\r");
    demo_check(strstr(host_capture_text(), "DDR3 arbiter not present in this build") != NULL, "ddr test: arbiter absent");

    /* Arbiter present, controller not calibrated: the test refuses. */
    host_model_ddr_set(1, 0);
    host_capture_clear();
    demo_type("ddr test 1\r");
    demo_check(strstr(host_capture_text(), "% DDR3 is not calibrated") != NULL &&
               strstr(host_capture_text(), "DDR3 test:") == NULL, "ddr test: refused before calibration");

    /* Calibrated: show ddr, then the default size and a given size. */
    host_model_ddr_set(1, 1);
    host_capture_clear();
    demo_type("show ddr\r");
    demo_check(strstr(host_capture_text(), "Calibration     : done") != NULL &&
               strstr(host_capture_text(), "ID \"ARBT\" 0x41524254, version 11-09-2026 at 0x44A04000") != NULL &&
               strstr(host_capture_text(), "2 master(s), 16-byte beats, ID width 1, 8 outstanding, high-priority mask 0x02, narrow mask 0x01, wrap mask 0x01") != NULL &&
               strstr(host_capture_text(), "illegal-burst flag clear") != NULL &&
               strstr(host_capture_text(), "Master 0 (CPU caches): AW bursts 0,") != NULL &&
               strstr(host_capture_text(), "Master 1 (video write DMA): AW bursts 0,") != NULL, "show ddr: calibrated, arbiter identity and counters");
    host_capture_clear();
    demo_type("ddr test\r");
    demo_check(strstr(host_capture_text(), "DDR3 test: 16 MiB at 0x80000000") != NULL &&
               strstr(host_capture_text(), "Data bus        : PASS") != NULL &&
               strstr(host_capture_text(), "Address bus     : PASS (22 address offsets)") != NULL &&
               strstr(host_capture_text(), "Random fill     : PASS (16 MiB written and verified)") != NULL &&
               strstr(host_capture_text(), "MB/s") != NULL &&
               strstr(host_capture_text(), "DDR3 test PASS") != NULL, "ddr test: default 16 MiB passes");
    host_capture_clear();
    demo_type("ddr test 0x2\r");
    demo_check(strstr(host_capture_text(), "DDR3 test: 2 MiB") != NULL && strstr(host_capture_text(), "DDR3 test PASS") != NULL,
               "ddr test 0x2: hexadecimal size accepted");
    host_capture_clear();
    demo_type("show ddr\r");
    demo_check(strstr(host_capture_text(), "Master 0 (CPU caches): AW bursts 0,") == NULL &&
               strstr(host_capture_text(), "Master 0 (CPU caches): AW bursts ") != NULL, "show ddr: counters count the test traffic");
    host_capture_clear();
    demo_type("clear counters\r");
    demo_type("show ddr\r");
    demo_check(strstr(host_capture_text(), "Master 0 (CPU caches): AW bursts 0, AR bursts 0, W beats 0, R beats 0, errors 0,") != NULL,
               "clear counters clears the arbiter");

    /* Bad arguments are rejected, not clamped. */
    static const char *const bad[] = { "ddr test 0\r", "ddr test 513\r", "ddr test 1000000\r", "ddr test abc\r", "ddr test 1.5\r",
                                       "ddr test -1\r" };
    for (size_t i = 0; i < sizeof(bad) / sizeof(bad[0]); i++) {
        char msg[96];
        host_capture_clear();
        demo_type(bad[i]);
        (void)snprintf(msg, sizeof(msg), "[%s]: rejected without running", bad[i]);
        demo_check(strstr(host_capture_text(), "% Invalid size in MiB (1..512)") != NULL &&
                   strstr(host_capture_text(), "DDR3 test:") == NULL, msg);
    }

    /* The test catches faults: an address line stuck low, a data bit stuck low. */
    host_model_ddr_clear();
    host_model_ddr_alias_bit(20);
    host_capture_clear();
    demo_type("ddr test 4\r");
    demo_check(strstr(host_capture_text(), "Address bus     : FAIL") != NULL &&
               strstr(host_capture_text(), "DDR3 test FAIL") != NULL &&
               strstr(host_capture_text(), "First mismatch  : address bus") != NULL, "ddr test: stuck address line caught");
    host_model_ddr_clear();
    host_model_ddr_data_and(~(1u << 17));
    host_capture_clear();
    demo_type("ddr test 1\r");
    demo_check(strstr(host_capture_text(), "Data bus        : FAIL") != NULL &&
               strstr(host_capture_text(), "Random fill     : FAIL") != NULL &&
               strstr(host_capture_text(), "DDR3 test FAIL") != NULL, "ddr test: stuck data bit caught");
    host_model_ddr_clear();

    /* The arbiter's error flag shows in show ddr and clears with clear counters. */
    host_model_ddr_error();
    host_capture_clear();
    demo_type("show ddr\r");
    demo_check(strstr(host_capture_text(), "illegal-burst flag SET") != NULL, "show ddr: illegal-burst flag set");
    demo_type("clear counters\r");
    host_capture_clear();
    demo_type("show ddr\r");
    demo_check(strstr(host_capture_text(), "illegal-burst flag clear") != NULL, "clear counters clears the illegal-burst flag");

    host_model_ddr_set(0, 0);
    host_model_ddr_clear();
    demo_type("disable\r");
}

/**
 * @brief Check that the console output since the last capture clear holds a text.
 * @param needle Text.
 * @return 1 when found.
 */
static int demo_has(const char *needle)
{
    return strstr(host_capture_text(), needle) != NULL;
}

/**
 * @brief Video path: show camera and show framebuffer without and with the cores, camera mode, source and rate
 *        (names, rejections, the mode and period interplay), the core's own rejection flags, framebuffer crc at both
 *        modes against the CRC-32 of the C bar model, with a stride, with no frame and after clear counters.
 * @return None.
 */
static void demo_video(void)
{
    /* The CRC-32 of the frames of the C bar model (cores/rtlnet_csi2_rx/testbench/csi2_bars_model.c). */
    static const char *const crc_720  = "0x6D3DF810 (frame 150, slot 2, 1280x720, pattern, 1843200 bytes)";
    static const char *const crc_1080 = "0x8ED9EC2B (frame 150, slot 2, 1920x1080, pattern, 4147200 bytes)";

    /* Cores absent. */
    host_model_video_set(0);
    host_capture_clear();
    demo_type("show camera\r");
    demo_check(demo_has("% rtlnet_csi2_rx not present in this build"), "show camera: core absent");
    host_capture_clear();
    demo_type("show framebuffer\r");
    demo_check(demo_has("% rtlnet_framebuf not present in this build"), "show framebuffer: core absent");
    demo_type("enable\r");
    host_capture_clear();
    demo_type("camera mode 1080p30\r");
    demo_check(demo_has("% rtlnet_csi2_rx not present in this build"), "camera mode: core absent");
    host_capture_clear();
    demo_type("framebuffer crc\r");
    demo_check(demo_has("% rtlnet_framebuf not present in this build"), "framebuffer crc: core absent");
    /* H.264 stream commands without the encoder core: refusals, QP validation, the status screens. */
    host_capture_clear();
    demo_type("stream h264 192.168.68.10 5004\r");
    demo_check(demo_has("% rtlnet_h264_enc not present in this build"), "stream h264: encoder absent");
    host_capture_clear();
    demo_type("stream h264 300.1.1.1 5004\r");
    demo_check(demo_has("% Invalid IPv4 address") || demo_has("IPv4 address"), "stream h264: bad address rejected");
    host_capture_clear();
    demo_type("encoder qp 60\r");
    demo_check(demo_has("QP (0..51)"), "encoder qp: 60 rejected");
    host_capture_clear();
    demo_type("encoder qp 8\r");
    demo_check(demo_has("the driver writes 12"), "encoder qp: 8 accepted with the floor note");
    host_capture_clear();
    demo_type("encoder qp 28\r");
    demo_check(demo_has("QP 28, effective at the next picture"), "encoder qp: 28 accepted");
    host_capture_clear();
    demo_type("encoder gop 0\r");
    demo_check(demo_has("GOP (1..255)"), "encoder gop: 0 rejected");
    host_capture_clear();
    demo_type("encoder gop 256\r");
    demo_check(demo_has("GOP (1..255)"), "encoder gop: 256 rejected");
    host_capture_clear();
    demo_type("encoder gop 1\r");
    demo_check(demo_has("GOP 1 (every picture is an IDR picture)"), "encoder gop: 1 accepted");
    host_capture_clear();
    demo_type("encoder gop 30\r");
    demo_check(demo_has("GOP 30 (an IDR picture every 30 pictures"), "encoder gop: 30 accepted");
    /* Rate control (Phase 2d): argument checks, the status lines, the history listing, the test pattern command. */
    host_capture_clear();
    demo_type("encoder bitrate 100001\r");
    demo_check(demo_has("bit rate in kb/s (0..100000"), "encoder bitrate: 100001 rejected");
    host_capture_clear();
    demo_type("encoder buffer 99\r");
    demo_check(demo_has("buffer in ms (100..2000)"), "encoder buffer: 99 rejected");
    host_capture_clear();
    demo_type("encoder buffer 2001\r");
    demo_check(demo_has("buffer in ms (100..2000)"), "encoder buffer: 2001 rejected");
    host_capture_clear();
    demo_type("encoder qprange 11 40\r");
    demo_check(demo_has("Invalid QP range"), "encoder qprange: min 11 rejected");
    host_capture_clear();
    demo_type("encoder qprange 40 20\r");
    demo_check(demo_has("Invalid QP range"), "encoder qprange: min above max rejected");
    host_capture_clear();
    demo_type("encoder qprange 20 52\r");
    demo_check(demo_has("Invalid QP range"), "encoder qprange: max 52 rejected");
    host_capture_clear();
    demo_type("encoder bitrate 1000\r");
    demo_check(demo_has("Constant bit rate 1000 kb/s, effective at the next picture (no IDR picture is forced)"), "encoder bitrate: 1000 accepted");
    host_capture_clear();
    demo_type("encoder buffer 250\r");
    demo_check(demo_has("Rate control buffer 250 ms"), "encoder buffer: 250 accepted");
    host_capture_clear();
    demo_type("encoder qprange 20 40\r");
    demo_check(demo_has("Rate control QP range 20..40"), "encoder qprange: 20..40 accepted");
    host_capture_clear();
    demo_type("show stream\r");
    demo_check(demo_has("  Rate control    : constant bit rate, target 1000 kb/s, buffer 250 ms (250000 bits), QP range 20..40") &&
               demo_has("  Measured rate   : 0 kb/s over the last 1 s, 0 kb/s over the last 10 s") &&
               demo_has("  Buffer fill     : 0.0 % (min 0.0 %, max 0.0 % since clear)") &&
               demo_has("  Picture QP      : last 0; since clear min 0, avg 0.00, max 0 (0 pictures)") &&
               demo_has("  Buffer events   : overflow 0 (0 below QP max), underflow 0") &&
               !demo_has("  Test pattern    :"), "show stream: rate control lines, constant bit rate (no pattern line without the core)");
    host_capture_clear();
    demo_type("encoder bitrate 0\r");
    demo_check(demo_has("Constant QP 28 (rate control off)"), "encoder bitrate: 0 returns to constant QP");
    demo_type("encoder qprange 12 51\r");
    demo_type("encoder buffer 500\r");
    host_capture_clear();
    demo_type("show stream\r");
    demo_check(demo_has("  Rate control    : constant QP 28 (target 0)") && demo_has("  Buffer fill     : not used in constant QP mode"),
               "show stream: constant QP lines");
    host_capture_clear();
    demo_type("show encoder history\r");
    demo_check(demo_has("Encoder history: 0 of 0 recorded seconds") && demo_has("Age (s)       Bits/s  QP avg  Fill %  Pictures"),
               "show encoder history: empty");
    host_capture_clear();
    demo_type("show encoder history 0\r");
    demo_check(demo_has("number of seconds (1..3600)"), "show encoder history: 0 rejected");
    host_capture_clear();
    demo_type("show encoder history 3601\r");
    demo_check(demo_has("number of seconds (1..3600)"), "show encoder history: 3601 rejected");
    host_capture_clear();
    demo_type("camera pattern stripes\r");
    demo_check(demo_has("test pattern (bars, scroll, box, noise or all)"), "camera pattern: bad name rejected");
    host_capture_clear();
    demo_type("camera pattern scroll 33\r");
    demo_check(demo_has("pattern speed (-32..32)"), "camera pattern: speed 33 rejected");
    host_capture_clear();
    demo_type("camera pattern scroll -33\r");
    demo_check(demo_has("pattern speed (-32..32)"), "camera pattern: speed -33 rejected");
    host_capture_clear();
    demo_type("camera pattern scroll 4\r");
    demo_check(demo_has("% rtlnet_csi2_rx not present in this build"), "camera pattern: core absent");

    host_capture_clear();
    demo_type("show stream\r");
    demo_check(demo_has("State           : stopped") && demo_has("QP 28") && demo_has("GOP             : 30 (IDR every 30 pictures)") && demo_has("CPU load        : TS mux 0.0 %"), "show stream: stopped, QP 28, GOP 30");
    host_capture_clear();
    demo_type("show encoder\r");
    demo_check(demo_has("% rtlnet_h264_enc not present in this build"), "show encoder: core absent");
    /* High profile seam: the encoder register model with the seam and the High profile status in its states. */
    host_capture_clear();
    demo_type("encoder profile high\r");
    demo_check(demo_has("% rtlnet_h264_enc not present in this build"), "encoder profile: core absent");
    demo_type("encoder notify polled\r");
    demo_check(demo_has("% rtlnet_h264_enc not present in this build") || demo_has("Notification polled"), "encoder notify polled: accepted without the core");
    host_model_h264_set(1, 1);   /* seam built, stage 1 netlist: present, licensed, unlimited, hp_caps 0 */
    /* Notification mode (interrupt registers present in the model): the request, the lines of show encoder and show stream, the self-test refusal. */
    host_capture_clear();
    demo_type("encoder notify polled\r");
    demo_check(demo_has("Notification polled: the main loop reads STATUS and starts the next picture (applied at the next stream start)"), "encoder notify polled: accepted, no stream");
    host_capture_clear();
    demo_type("show encoder\r");
    demo_check(demo_has("  Notification    : polled (requested; applied at the next stream start)") && demo_has("interrupt registers present"),
               "show encoder: notification line polled, interrupt registers present");
    host_capture_clear();
    demo_type("encoder notify interrupt\r");
    demo_check(demo_has("Notification interrupt requested: the encoder interrupt starts the next picture (applied at the next stream start)"), "encoder notify interrupt: accepted, no stream");
    host_capture_clear();
    demo_type("encoder notify bogus\r");
    demo_check(demo_has("notification mode (interrupt or polled)"), "encoder notify: bad word rejected");
    host_capture_clear();
    demo_type("encoder irqtest\r");
    demo_check(demo_has("The interrupt test needs a running stream in interrupt mode"), "encoder irqtest: refused without a stream");
    host_capture_clear();
    demo_type("show stream\r");
    demo_check(demo_has("  Notification    : interrupt (requested; applied at the next stream start)") && demo_has("  Interrupts      : 0 taken (0 with no enabled event); picture done 0, error 0, ring stall 0, profile change 0, license lost 0"),
               "show stream: notification line and zero interrupt counts while stopped");
    host_model_h264_irq_caps(0);   /* an older core: no interrupt registers */
    host_model_h264_set(1, 1);
    host_capture_clear();
    demo_type("show encoder\r");
    demo_check(demo_has("interrupt registers absent (polled mode only)") && !demo_has("Interrupt regs"), "show encoder: older core, interrupt registers absent");
    host_model_h264_irq_caps(1);
    host_model_h264_set(1, 1);
    host_capture_clear();
    demo_type("show encoder\r");
    demo_check(demo_has("  High profile    : present, licensed, time left unlimited, tools none (hp_caps 0), profile baseline, 0 forced IDR pictures"),
               "show encoder: High profile line, stage 1 netlist unlimited");
    host_capture_clear();
    demo_type("encoder profile high\r");
    demo_check(demo_has("% Profile high refused: the High profile module offers no tool yet (hp_caps is 0)") && host_model_h264_hp_ctrl() == 0u,
               "encoder profile high: refused with hp_caps 0, nothing written");
    host_capture_clear();
    demo_type("encoder profile baseline\r");
    demo_check(demo_has("Profile baseline (Constrained Baseline), effective at the next picture"), "encoder profile baseline accepted");
    host_capture_clear();
    demo_type("encoder profile main\r");
    demo_check(demo_has("profile (baseline or high)"), "encoder profile: bad name rejected");
    host_model_h264_hp(1u, 1u, 0u, 1781u);   /* demo netlist: 29 min 41 s left */
    host_capture_clear();
    demo_type("show encoder\r");
    demo_check(demo_has("  High profile    : present, licensed, time left 29 min 41 s, tools none (hp_caps 0), profile baseline, 0 forced IDR pictures"),
               "show encoder: High profile line, demo netlist with time left");
    host_model_h264_hp(1u, 0u, 0u, 0u);      /* the license has ended */
    host_capture_clear();
    demo_type("show encoder\r");
    demo_check(demo_has("  High profile    : present, license ended, time left 0 min 0 s, tools none (hp_caps 0), profile baseline"),
               "show encoder: High profile line, license ended");
    host_model_h264_hp(1u, 1u, RTLNET_H264_CTL_HP_CAP_CABAC, 600u);   /* a later stage: CABAC offered */
    host_capture_clear();
    demo_type("encoder profile high\r");
    demo_check(demo_has("Profile high, effective at the next picture") && host_model_h264_hp_ctrl() == 1u, "encoder profile high: accepted with hp_caps");
    host_capture_clear();
    demo_type("show encoder\r");
    demo_check(demo_has("  High profile    : present, licensed, time left 10 min 0 s, tools CABAC (hp_caps 1), profile high, 0 forced IDR pictures"),
               "show encoder: High profile line, CABAC offered, profile high");
    /* Stage 3: the 8x8 transform request (HP_CTRL bit 1), refused while the module offers no transform. */
    host_capture_clear();
    demo_type("encoder transform8x8 on\r");
    demo_check(demo_has("% Transform8x8 on refused: the High profile module offers no 8x8 transform (hp_caps bit 1 is 0)") && host_model_h264_hp_ctrl_t8() == 0u,
               "encoder transform8x8 on: refused with hp_caps bit 1 clear, nothing written");
    host_capture_clear();
    demo_type("show encoder\r");
    demo_check(demo_has("  Transform 8x8   : not offered (hp_caps bit 1 is 0)"), "show encoder: Transform 8x8 line, not offered");
    host_model_h264_hp(1u, 1u, RTLNET_H264_CTL_HP_CAP_CABAC | RTLNET_H264_CTL_HP_CAP_TRANSFORM8X8, 600u);   /* stage 3: CABAC and the 8x8 transform */
    host_capture_clear();
    demo_type("show encoder\r");
    demo_check(demo_has("  Transform 8x8   : off, not in force (4x4 transform)") && host_model_h264_hp_ctrl_t8() == 0u,
               "show encoder: the transform request starts at off (the default is the 4x4 transform)");
    host_capture_clear();
    demo_type("encoder transform8x8 on\r");
    demo_check(demo_has("Transform8x8 on, effective at the next picture in the High profile") && host_model_h264_hp_ctrl_t8() == 1u,
               "encoder transform8x8 on: accepted, HP_CTRL bit 1 set");
    host_capture_clear();
    demo_type("show encoder\r");
    demo_check(demo_has("  High profile    : present, licensed, time left 10 min 0 s, tools CABAC 8x8-transform (hp_caps 3), profile high, 0 forced IDR pictures") &&
               demo_has("  Transform 8x8   : on, in force (inter macroblocks use the 8x8 transform)"),
               "show encoder: Transform 8x8 line, on and in force");
    host_capture_clear();
    demo_type("encoder transform8x8 off\r");
    demo_check(demo_has("Transform8x8 off (4x4 transform), effective at the next picture") && host_model_h264_hp_ctrl_t8() == 0u && host_model_h264_hp_ctrl() == 1u,
               "encoder transform8x8 off: HP_CTRL bit 1 cleared, hp_enable kept");
    host_capture_clear();
    demo_type("show encoder\r");
    demo_check(demo_has("  Transform 8x8   : off, not in force (4x4 transform)"), "show encoder: Transform 8x8 line, off");
    host_capture_clear();
    demo_type("encoder transform8x8 maybe\r");
    demo_check(demo_has("state (on, off or auto)"), "encoder transform8x8: bad word rejected");
    host_capture_clear();
    demo_type("encoder transform8x8 on\r");
    demo_check(host_model_h264_hp_ctrl_t8() == 1u && host_model_h264_hp_ctrl_auto() == 0u, "encoder transform8x8 on again");
    /* Stage 3a: the adaptive choice, the macroblock counts of the last picture in show encoder. */
    host_model_h264_hp(1u, 1u, RTLNET_H264_CTL_HP_CAP_CABAC | RTLNET_H264_CTL_HP_CAP_TRANSFORM8X8, 600u);   /* a netlist with bits 0 and 1 only: auto refused */
    host_capture_clear();
    demo_type("encoder transform8x8 auto\r");
    demo_check(demo_has("% Transform8x8 auto refused: the High profile module offers no adaptive transform choice (hp_caps bit 2 is 0)") && host_model_h264_hp_ctrl_auto() == 0u,
               "encoder transform8x8 auto: refused with hp_caps bit 2 clear");
    host_model_h264_hp(1u, 1u, RTLNET_H264_CTL_HP_CAP_CABAC | RTLNET_H264_CTL_HP_CAP_TRANSFORM8X8 | RTLNET_H264_CTL_HP_CAP_ADAPTIVE, 600u);
    host_model_h264_t8_counts(321u, 45u);
    host_capture_clear();
    demo_type("show encoder\r");
    demo_check(demo_has("  Transform 8x8   : on, in force (inter macroblocks use the 8x8 transform)") && demo_has("  Transform MBs   : last picture 8x8 321, 4x4 45"),
               "show encoder: Transform 8x8 on, macroblock counts");
    host_capture_clear();
    demo_type("encoder transform8x8 auto\r");
    demo_check(demo_has("Transform8x8 auto, effective at the next picture in the High profile") && host_model_h264_hp_ctrl_t8() == 1u &&
               host_model_h264_hp_ctrl_auto() == 1u && host_model_h264_hp_ctrl() == 1u, "encoder transform8x8 auto: accepted, HP_CTRL bits 1 and 2 set, hp_enable kept");
    host_model_h264_t8_counts(100u, 200u);
    host_capture_clear();
    demo_type("show encoder\r");
    demo_check(demo_has("  Transform 8x8   : auto, in force (the module chooses the 4x4 or the 8x8 transform per macroblock)") &&
               demo_has("  Transform MBs   : last picture 8x8 100, 4x4 200"), "show encoder: Transform 8x8 auto, macroblock counts");
    host_capture_clear();
    demo_type("encoder transform8x8 off\r");
    demo_check(demo_has("Transform8x8 off (4x4 transform), effective at the next picture") && host_model_h264_hp_ctrl_t8() == 0u && host_model_h264_hp_ctrl_auto() == 0u,
               "encoder transform8x8 off after auto: bits 1 and 2 cleared");
    host_capture_clear();
    demo_type("show encoder\r");
    demo_check(demo_has("  Transform 8x8   : off, not in force (4x4 transform)") && !demo_has("  Transform MBs   :"), "show encoder: Transform 8x8 off, no macroblock counts");
    host_model_h264_hp(1u, 1u, RTLNET_H264_CTL_HP_CAP_CABAC, 600u);
    host_capture_clear();
    demo_type("encoder transform8x8 auto\r");
    demo_check(demo_has("% Transform8x8 auto refused: the High profile module offers no 8x8 transform (hp_caps bit 1 is 0)") && host_model_h264_hp_ctrl_auto() == 0u,
               "encoder transform8x8 auto: refused with hp_caps bit 1 clear");
    host_model_h264_hp(1u, 1u, RTLNET_H264_CTL_HP_CAP_CABAC | RTLNET_H264_CTL_HP_CAP_TRANSFORM8X8 | RTLNET_H264_CTL_HP_CAP_ADAPTIVE, 600u);
    host_capture_clear();
    demo_type("encoder transform8x8 on\r");
    demo_check(host_model_h264_hp_ctrl_t8() == 1u, "encoder transform8x8 on, last");
    host_model_h264_hp(1u, 1u, RTLNET_H264_CTL_HP_CAP_CABAC, 600u);   /* back to the CABAC-only module for the checks below */
    host_model_h264_hp(1u, 0u, RTLNET_H264_CTL_HP_CAP_CABAC, 0u);
    host_capture_clear();
    demo_type("encoder profile high\r");
    demo_check(demo_has("% Profile high refused: the High profile license has ended"), "encoder profile high: refused, license ended");
    host_model_h264_hp(0u, 0u, 0u, 0u);      /* the simulation stub */
    host_capture_clear();
    demo_type("show encoder\r");
    demo_check(demo_has("  High profile    : not present (the High profile netlist is not in this build)"), "show encoder: High profile line, stub");
    host_capture_clear();
    demo_type("encoder profile high\r");
    demo_check(demo_has("% Profile high refused: the High profile netlist is not in this build (simulation stub)"), "encoder profile high: refused, stub");
    host_model_h264_set(1, 0);               /* no seam in the build */
    host_capture_clear();
    demo_type("show encoder\r");
    demo_check(demo_has("  High profile    : not present (this build has no High profile seam)"), "show encoder: High profile line, no seam");
    host_capture_clear();
    demo_type("encoder profile high\r");
    demo_check(demo_has("% Profile high refused: this build has no High profile seam (CAPS HP_SEAM 0)"), "encoder profile high: refused, no seam");
    host_model_h264_set(0, 0);
    host_capture_clear();
    demo_type("stream stop\r");
    demo_check(demo_has("No stream is running"), "stream stop: nothing running");

    /* Reset state: 720p30, auto, pattern active, 30.00 fps. */
    host_model_video_set(1);
    host_model_video_frames(150u);
    host_capture_clear();
    demo_type("show camera\r");
    demo_check(demo_has("  Video mode      : 720p30 (1280x720)") && demo_has("  Source setting  : auto") &&
               demo_has("  Active source   : pattern") && demo_has("  Frame period    : 3000000 ui_clk cycles (30.00 fps)") &&
               demo_has("  Frame count     : 150") && demo_has("  Camera timeout  : 2 frame periods") &&
               demo_has("  Status          : 0x00000001 (pattern-active)"), "show camera: reset state");
    demo_check(demo_has("  Test pattern    : bars, speed 4 px/frame, frame 0 since the last restart"), "show camera: pattern reset state");
    host_capture_clear();
    demo_type("camera pattern box -7\r");
    demo_check(demo_has("Test pattern box, speed -7, effective at the next frame"), "camera pattern: box -7 accepted");
    host_capture_clear();
    demo_type("show camera\r");
    demo_check(demo_has("  Test pattern    : box, speed -7 px/frame"), "show camera: pattern box -7 read back");
    host_capture_clear();
    demo_type("camera pattern all\r");
    demo_check(demo_has("Test pattern all, speed 4, effective at the next frame"), "camera pattern: default speed 4");
    host_capture_clear();
    demo_type("camera pattern bars\r");
    demo_check(demo_has("Test pattern bars, speed 4"), "camera pattern: back to bars");
    host_capture_clear();
    demo_type("show framebuffer\r");
    demo_check(demo_has("  Slots           : 3 x 4096 KiB from DDR3 offset 0x10000000 (CPU 0x90000000)") &&
               demo_has("  Latest          : slot 2, frame 150, 1280x720, pattern, timestamp ") &&
               demo_has("  Firmware holds  : none") && demo_has("  Published       : 150, dropped 0, bad 0") &&
               demo_has("  Reference counts: slot 0 0, slot 1 0, slot 2 0") &&
               demo_has("  Write DMA       : frames ok 150, bad 0, dropped 0, bursts "), "show framebuffer: published frames");

    /* CRC at 720p30 and 1080p30 against the C model; the slot is released afterwards. */
    host_capture_clear();
    demo_type("framebuffer crc\r");
    demo_check(demo_has("Framebuffer CRC-32 : ") && demo_has(crc_720) && !host_model_video_fw_holds(), "framebuffer crc: 720p30 equals the C model");
    host_capture_clear();
    demo_type("camera mode 1080p30\r");
    demo_check(demo_has("Video mode 1080p30 (1920x1080), effective at the next frame"), "camera mode 1080p30");
    host_capture_clear();
    demo_type("show camera\r");
    demo_check(demo_has("  Video mode      : 1080p30 (1920x1080)"), "show camera: 1080p30");
    host_capture_clear();
    demo_type("framebuffer crc\r");
    demo_check(demo_has(crc_1080) && !host_model_video_fw_holds(), "framebuffer crc: 1080p30 equals the C model");
    demo_type("camera mode 720p30\r");

    /* A stride: the same frame at 5120 bytes per line gives the same CRC. */
    demo_type("debug write 0x44A06014 5120\r");
    host_capture_clear();
    demo_type("framebuffer crc\r");
    demo_check(demo_has(crc_720), "framebuffer crc: strided lines, same CRC");
    demo_type("debug write 0x44A06014 0\r");

    /* Modes, sources and rates: names, bad values, rejection flags. */
    host_capture_clear();
    demo_type("camera mode 4k\r");
    demo_check(demo_has("% Invalid video mode (720p30 or 1080p30) \"4k\""), "camera mode: bad name rejected");
    host_capture_clear();
    demo_type("camera source camera\r");
    demo_check(demo_has("Video source camera"), "camera source camera");
    host_capture_clear();
    demo_type("show camera\r");
    demo_check(demo_has("  Source setting  : camera") && demo_has("  Active source   : camera") &&
               demo_has("  Status          : 0x00000000 (none)"), "show camera: camera only");
    demo_type("camera source pattern\r");
    demo_type("camera source auto\r");
    host_capture_clear();
    demo_type("camera source radar\r");
    demo_check(demo_has("% Invalid video source"), "camera source: bad name rejected");
    host_capture_clear();
    demo_type("camera rate 15\r");
    demo_check(demo_has("Frame rate 15 fps (6000000 ui_clk cycles per frame)"), "camera rate 15");
    host_capture_clear();
    demo_type("show camera\r");
    demo_check(demo_has("  Frame period    : 6000000 ui_clk cycles (15.00 fps)"), "show camera: 15 fps");
    static const char *const bad_rate[] = { "camera rate 0\r", "camera rate 31\r", "camera rate abc\r", "camera rate -1\r" };
    for (unsigned i = 0; i < sizeof(bad_rate) / sizeof(bad_rate[0]); i++) {
        host_capture_clear();
        demo_type(bad_rate[i]);
        demo_check(demo_has("% Invalid frame rate in fps (1..30)") && !demo_has("Frame rate "), "camera rate: out of range rejected");
    }
    demo_type("camera rate 30\r");
    /* The mode and period interplay: a period below the 720p30 minimum is legal at 1080p30 and blocks the switch back. */
    demo_type("camera mode 1080p30\r");
    demo_type("debug write 0x44A05018 2999500\r");
    host_capture_clear();
    demo_type("camera mode 720p30\r");
    demo_check(demo_has("% Video mode 720p30 rejected: the frame period is below its minimum"), "camera mode: rejected below the minimum period");
    host_capture_clear();
    demo_type("show camera\r");
    demo_check(demo_has("  Video mode      : 1080p30 (1920x1080)") && demo_has("  Frame period    : 2999500 ui_clk cycles (30.00 fps)") &&
               demo_has("  Status          : 0x00000001 (pattern-active)"), "show camera: rejected mode leaves the register and clears the flag");
    demo_type("debug write 0x44A05018 3000000\r");
    demo_type("camera mode 720p30\r");
    /* Writes the driver does not make: the core's flags show in show camera. */
    demo_type("debug write 0x44A05010 5\r");
    demo_type("debug write 0x44A05014 3\r");
    host_capture_clear();
    demo_type("show camera\r");
    demo_check(demo_has("MODE_ERR") && demo_has("SOURCE_ERR") && demo_has("  Video mode      : 720p30"), "show camera: MODE_ERR and SOURCE_ERR flags");
    demo_type("debug write 0x44A05020 0x3C\r");

    /* No frame, then a slot held by the firmware, then clear counters. */
    host_model_video_frames(0u);
    host_capture_clear();
    demo_type("show framebuffer\r");
    demo_check(demo_has("  Latest          : none published"), "show framebuffer: none published");
    host_capture_clear();
    demo_type("framebuffer crc\r");
    demo_check(demo_has("% No frame published yet"), "framebuffer crc: no frame published");
    host_model_video_frames(150u);
    demo_type("debug write 0x44A0700C 1\r");
    host_capture_clear();
    demo_type("show framebuffer\r");
    demo_check(demo_has("  Firmware holds  : slot 2") && demo_has("  Reference counts: slot 0 0, slot 1 0, slot 2 1"), "show framebuffer: firmware holds a slot");
    host_capture_clear();
    demo_type("framebuffer crc\r");
    demo_check(demo_has("% No frame published yet (or the firmware already holds a slot)"), "framebuffer crc: refused while a slot is held");
    demo_type("debug write 0x44A0700C 2\r");
    demo_check(!host_model_video_fw_holds(), "framebuffer: release by register");
    demo_type("clear counters\r");
    host_capture_clear();
    demo_type("show framebuffer\r");
    demo_check(demo_has("  Published       : 0, dropped 0, bad 0") && demo_has("  Write DMA       : frames ok 0, bad 0, dropped 0, bursts 0, beats 0"),
               "clear counters clears the video counters");
    host_model_video_set(0);
    demo_type("disable\r");
}

/**
 * @brief Run one scripted step and check its output and the mode afterwards.
 * @param st Step.
 * @return None.
 */
static void demo_run_step(const demo_step_t *st)
{
    char msg[256];
    host_capture_clear();
    demo_type(st->input);
    for (int i = 0; i < 4 && st->expect[i] != NULL; i++) {
        (void)snprintf(msg, sizeof(msg), "input [%s]: expected \"%s\"", st->input, st->expect[i]);
        demo_check(strstr(host_capture_text(), st->expect[i]) != NULL, msg);
    }
    if (st->reject != NULL) {
        (void)snprintf(msg, sizeof(msg), "input [%s]: unexpected \"%s\"", st->input, st->reject);
        demo_check(strstr(host_capture_text(), st->reject) == NULL, msg);
    }
    (void)snprintf(msg, sizeof(msg), "input [%s]: mode %s, expected %s", st->input,
                   Menu_ModeName(Menu_GetMode()), Menu_ModeName(st->mode_after));
    demo_check(Menu_GetMode() == st->mode_after, msg);
}

